// generated by build-games: content/games/<slug>.html -> bu fayl. Əl ilə dəyişmə; node scripts/build-games.mjs işlət.
export default "<!doctype html>\n<html lang=\"az\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<title>Yaddaş kartları</title>\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;min-height:100%;background:radial-gradient(circle at 50% 0,#17224a,#070b18 70%);color:#e8f0ff;font-family:system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;-webkit-user-select:none;user-select:none}\nbody{display:flex;justify-content:center;padding:10px}\n.wrap{width:100%;max-width:460px;text-align:center}\nh1{margin:6px 0 8px;font-size:24px;letter-spacing:.5px}\n.hud{display:flex;justify-content:space-between;gap:8px;margin:6px 0;font-size:15px}\n.hud span{flex:1;background:#ffffff12;border:1px solid #ffffff22;border-radius:10px;padding:6px 8px}\ncanvas{display:block;margin:0 auto;width:100%;height:auto;border-radius:14px;border:2px solid #4cc9f0;background:#0a1128;touch-action:none;box-shadow:0 0 24px #4cc9f044}\nbutton{font:inherit;color:#fff;background:linear-gradient(#3a86ff,#2563eb);border:0;border-radius:12px;padding:10px 16px;cursor:pointer;box-shadow:0 3px 0 #1b3f9a}\nbutton:active{transform:translateY(2px);box-shadow:none}\n.row{display:flex;gap:8px;justify-content:center;margin:10px 0;flex-wrap:wrap}\n.hint{opacity:.7;font-size:13px;margin:6px 0}\n.msg{min-height:24px;font-weight:700;color:#ffd166;margin:6px 0}\n.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px auto;max-width:380px}\n.card{aspect-ratio:1;position:relative;padding:0;background:none;box-shadow:none;perspective:600px;border-radius:12px}\n.card i{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;border-radius:12px;font-style:normal;backface-visibility:hidden;-webkit-backface-visibility:hidden;transition:transform .35s}\n.card .f{background:linear-gradient(135deg,#3a86ff,#7b2ff7);font-size:26px;border:2px solid #ffffff44}\n.card .b{background:#16204a;border:2px solid #4cc9f0;font-size:clamp(28px,10vw,44px);transform:rotateY(180deg)}\n.card.on .f{transform:rotateY(180deg)}.card.on .b{transform:rotateY(0)}\n.card.ok .b{background:#2d6a4f;border-color:#7ae582}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<h1>🧠 Yaddaş kartları</h1>\n<div class=\"hud\"><span>Gediş: <b id=\"mv\">0</b></span><span>Vaxt: <b id=\"tm\">0</b> san</span><span>Rekord: <b id=\"bs\">-</b></span></div>\n<div class=\"grid\" id=\"g\"></div>\n<div class=\"msg\" id=\"msg\"></div>\n<div class=\"row\"><button id=\"re\">Yenidən başla</button></div>\n<p class=\"hint\">Eyni şəkilli kartların cütlərini tap</p>\n</div>\n<script>\nconst ICONS = ['🍎', '🚀', '🐱', '⚽', '🎧', '🌙', '🍕', '🔥'];\nconst $ = id => document.getElementById(id);\nlet open, lock, moves, found, secs, timer, best = 0;\ntry { best = +localStorage.getItem('nibras_yaddas') || 0; } catch (e) {}\nif (best) $('bs').textContent = best + ' gediş';\n\nfunction shuffle(a) { for (let i = a.length - 1; i > 0; i--) { const j = Math.random() * (i + 1) | 0; [a[i], a[j]] = [a[j], a[i]]; } return a; }\nfunction start() {\n  clearInterval(timer); open = []; lock = false; moves = 0; found = 0; secs = 0; timer = null;\n  $('mv').textContent = 0; $('tm').textContent = 0; $('msg').textContent = '';\n  const g = $('g'); g.innerHTML = '';\n  shuffle(ICONS.concat(ICONS)).forEach((ic, i) => {\n    const c = document.createElement('button'); c.className = 'card'; c.dataset.v = ic;\n    c.setAttribute('aria-label', 'Kart ' + (i + 1));\n    c.innerHTML = '<i class=\"f\">?</i><i class=\"b\">' + ic + '</i>';\n    c.onclick = () => flip(c); g.appendChild(c);\n  });\n}\nfunction flip(c) {\n  if (lock || c.classList.contains('on')) return;\n  if (!timer) timer = setInterval(() => { secs++; $('tm').textContent = secs; }, 1000);\n  c.classList.add('on'); open.push(c);\n  if (open.length < 2) return;\n  moves++; $('mv').textContent = moves;\n  const [a, b] = open;\n  if (a.dataset.v === b.dataset.v) {\n    a.classList.add('ok'); b.classList.add('ok'); open = []; found++;\n    if (found === ICONS.length) win();\n  } else {\n    lock = true;\n    setTimeout(() => { a.classList.remove('on'); b.classList.remove('on'); open = []; lock = false; }, 800);\n  }\n}\nfunction win() {\n  clearInterval(timer);\n  $('msg').textContent = 'Əla! ' + moves + ' gedişdə ' + secs + ' saniyəyə tapdın 🎉';\n  if (!best || moves < best) { best = moves; $('bs').textContent = best + ' gediş'; try { localStorage.setItem('nibras_yaddas', best); } catch (e) {} }\n}\n$('re').onclick = start;\nstart();\n\n</script>\n</body>\n</html>\n";
